    const OVERLAY_STORAGE_KEY = "ilgc_supabase_overlay_v3";

    function loadOverlay() {
        try {
            const raw = localStorage.getItem(OVERLAY_STORAGE_KEY);
            return raw ? JSON.parse(raw) : {};
        } catch (e) {
            console.warn("Could not parse overlay from localStorage:", e);
            return {};
        }
    }

    function saveOverlay(overlay) {
        try {
            localStorage.setItem(OVERLAY_STORAGE_KEY, JSON.stringify(overlay));
        } catch (e) {
            console.warn("Could not save overlay to localStorage:", e);
        }
    }

    // Merge base DB with localStorage overlay
    function getMergedDB() {
        const overlay = loadOverlay();
        const merged = {};
        for (const [table, rows] of Object.entries(BASE_DB)) {
            let tableRows = [...rows];
            if (overlay[table]) {
                if (overlay[table].inserted) {
                    tableRows = [...tableRows, ...overlay[table].inserted];
                }
                if (overlay[table].updated) {
                    const updates = overlay[table].updated;
                    tableRows = tableRows.map(r => {
                        const key = r.id || r.email || r.project_code || r.file_id || r.workspace_id;
                        return updates[key] ? { ...r, ...updates[key] } : r;
                    });
                }
                if (overlay[table].deleted) {
                    const deletedSet = new Set(overlay[table].deleted);
                    tableRows = tableRows.filter(r => {
                        const key = r.id || r.email || r.project_code || r.file_id || r.workspace_id;
                        return !deletedSet.has(key);
                    });
                }
            }
            merged[table] = tableRows;
        }
        return merged;
    }

    // Live state in memory
    let liveDB = getMergedDB();

    function persistInsert(table, row) {
        const overlay = loadOverlay();
        if (!overlay[table]) overlay[table] = { inserted: [], updated: {}, deleted: [] };
        if (!overlay[table].inserted) overlay[table].inserted = [];
        overlay[table].inserted.push(row);
        saveOverlay(overlay);
        if (!liveDB[table]) liveDB[table] = [];
        liveDB[table].push(row);
    }

    function persistUpdate(table, keyCol, keyVal, updateFields) {
        const overlay = loadOverlay();
        if (!overlay[table]) overlay[table] = { inserted: [], updated: {}, deleted: [] };
        if (!overlay[table].updated) overlay[table].updated = {};
        overlay[table].updated[keyVal] = { ...(overlay[table].updated[keyVal] || {}), ...updateFields };
        saveOverlay(overlay);
        if (liveDB[table]) {
            liveDB[table] = liveDB[table].map(r => {
                if (String(r[keyCol]) === String(keyVal)) {
                    return { ...r, ...updateFields };
                }
                return r;
            });
        }
    }

    function persistDelete(table, keyCol, keyVal) {
        const overlay = loadOverlay();
        if (!overlay[table]) overlay[table] = { inserted: [], updated: {}, deleted: [] };
        if (!overlay[table].deleted) overlay[table].deleted = [];
        overlay[table].deleted.push(keyVal);
        saveOverlay(overlay);
        if (liveDB[table]) {
            liveDB[table] = liveDB[table].filter(r => String(r[keyCol]) !== String(keyVal));
        }
    }

    // Resolve user helper for login & queries
    window.resolveUserEmail = function (input, role) {
        if (!input) {
            if (role === "faculty") return "anil.roy@plaksha.edu.in";
            if (role === "ilgc") return "malini.balakrishnan@plaksha.edu.in";
            return "param.sharma.ug25@plaksha.edu.in";
        }

        const trimmed = input.trim().toLowerCase();

        // 1. Exact email match
        const exact = liveDB.users.find(u => u.email.toLowerCase() === trimmed);
        if (exact) return exact.email;

        // 2. Partial match in email or name
        const roleUsers = role
            ? liveDB.users.filter(u => role === "faculty" ? u.role === "mentor" : (role === "ilgc" ? (u.role === "ilgc_faculty" || u.role === "mentor") : u.role === "student"))
            : liveDB.users;

        const partial = roleUsers.find(u =>
            u.email.toLowerCase().includes(trimmed) ||
            u.name.toLowerCase().includes(trimmed)
        );
        if (partial) return partial.email;

        // Any user partial match
        const anyMatch = liveDB.users.find(u =>
            u.email.toLowerCase().includes(trimmed) ||
            u.name.toLowerCase().includes(trimmed)
        );
        if (anyMatch) return anyMatch.email;

        // 3. User typed a custom user ID / email
        const customEmail = trimmed.includes("@") ? trimmed : trimmed + "@plaksha.edu.in";
        const formattedName = trimmed.split("@")[0].replace(/[^a-zA-Z0-9]/g, " ").replace(/\b\w/g, c => c.toUpperCase()).trim();

        // Register custom user on the fly
        const newUserRole = role === "faculty" ? "mentor" : (role === "ilgc" ? "ilgc_faculty" : "student");
        const newUser = {
            email: customEmail,
            name: (role === "faculty" || role === "ilgc" ? "Dr. " : "") + formattedName,
            role: newUserRole,
            avatar_url: null,
            is_active: true,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString()
        };
        persistInsert("users", newUser);

        if (newUserRole === "student") {
            persistInsert("student_profiles", {
                email: customEmail,
                roll_number: "2025UG9999",
                program: "B.Tech Computer Science & Artificial Intelligence",
                department: "Computer Science & Engineering",
                semester: 5
            });
            persistInsert("project_members", {
                project_code: "FP1",
                student_email: customEmail,
                member_role: "Member",
                joined_at: new Date().toISOString(),
                left_at: null
            });
        } else {
            persistInsert("mentor_profiles", {
                email: customEmail,
                name: newUser.name,
                designation: role === "ilgc" ? "Director & Professor, ILGC" : "Associate Professor",
                department: "Computer Science & Engineering",
                bio: "Faculty mentor at Plaksha University."
            });
            persistInsert("project_mentors", {
                project_code: "FP1",
                mentor_email: customEmail,
                mentor_role: "Primary Mentor"
            });
            persistInsert("project_mentors", {
                project_code: "FP13",
                mentor_email: customEmail,
                mentor_role: "Primary Mentor"
            });
        }

        return customEmail;
    };

    // Query builder
    function createQueryBuilder(table) {
        let rows = liveDB[table] ? [...liveDB[table]] : [];
        let isSingle = false;
        let isMaybeSingle = false;
        let pendingUpdates = null;
        let isDelete = false;

        const builder = {
            select(cols) {
                return builder;
            },
            eq(col, val) {
                const searchVal = String(val).toLowerCase();
                rows = rows.filter(r => {
                    const rVal = r[col];
                    if (rVal === null || rVal === undefined) return false;
                    return String(rVal).toLowerCase() === searchVal;
                });
                return builder;
            },
            neq(col, val) {
                const searchVal = String(val).toLowerCase();
                rows = rows.filter(r => {
                    const rVal = r[col];
                    if (rVal === null || rVal === undefined) return true;
                    return String(rVal).toLowerCase() !== searchVal;
                });
                return builder;
            },
            is(col, val) {
                if (val === null) {
                    rows = rows.filter(r => r[col] === null || r[col] === undefined || r[col] === "");
                } else {
                    rows = rows.filter(r => r[col] === val);
                }
                return builder;
            },
            in(col, vals) {
                const valSet = new Set((vals || []).map(v => String(v).toLowerCase()));
                rows = rows.filter(r => {
                    const rVal = r[col];
                    if (rVal === null || rVal === undefined) return false;
                    return valSet.has(String(rVal).toLowerCase());
                });
                return builder;
            },
            order(col, opts) {
                const asc = !opts || opts.ascending !== false;
                rows.sort((a, b) => {
                    const av = a[col] ?? "";
                    const bv = b[col] ?? "";
                    if (av < bv) return asc ? -1 : 1;
                    if (av > bv) return asc ? 1 : -1;
                    return 0;
                });
                return builder;
            },
            limit(num) {
                rows = rows.slice(0, num);
                return builder;
            },
            range(from, to) {
                rows = rows.slice(from, to + 1);
                return builder;
            },
            single() {
                isSingle = true;
                return builder;
            },
            maybeSingle() {
                isMaybeSingle = true;
                return builder;
            },
            insert(data) {
                const items = Array.isArray(data) ? data : [data];
                items.forEach(item => {
                    persistInsert(table, item);
                });
                rows = items;
                return builder;
            },
            update(data) {
                pendingUpdates = data;
                return builder;
            },
            delete() {
                isDelete = true;
                return builder;
            },
            then(onFulfilled, onRejected) {
                if (pendingUpdates) {
                    rows.forEach(r => {
                        const keyCol = r.id ? "id" : (r.email ? "email" : (r.project_code ? "project_code" : (r.file_id ? "file_id" : (r.workspace_id ? "workspace_id" : Object.keys(r)[0]))));
                        const keyVal = r[keyCol];
                        persistUpdate(table, keyCol, keyVal, pendingUpdates);
                        Object.assign(r, pendingUpdates);
                    });
                }
                if (isDelete) {
                    rows.forEach(r => {
                        const keyCol = r.id ? "id" : (r.file_id ? "file_id" : (r.workspace_id ? "workspace_id" : (r.project_code ? "project_code" : Object.keys(r)[0])));
                        const keyVal = r[keyCol];
                        persistDelete(table, keyCol, keyVal);
                    });
                }

                let finalData;
                if (isSingle) {
                    finalData = rows.length > 0 ? rows[0] : null;
                } else if (isMaybeSingle) {
                    finalData = rows.length > 0 ? rows[0] : null;
                } else {
                    finalData = [...rows];
                }

                const response = {
                    data: finalData,
                    error: null,
                    count: rows.length
                };
                return Promise.resolve(response).then(onFulfilled, onRejected);
            },
            catch(onRejected) {
                return builder.then(null, onRejected);
            }
        };

        return builder;
    }

    // RPC support
    function handleRpc(fnName, args) {
        if (fnName === "review_expression_of_interest") {
            const { p_student_email, p_project_code, p_action, p_comment } = args || {};
            const eoiList = liveDB.expressions_of_interest || [];
            const target = eoiList.find(e =>
                e.student_email.toLowerCase() === String(p_student_email).toLowerCase() &&
                e.project_code.toLowerCase() === String(p_project_code).toLowerCase()
            );

            const newStatus = p_action === "accepted" ? "Accepted" : "Rejected";
            if (target) {
                target.status = newStatus;
                target.review_comment = p_comment || target.review_comment;
                target.reviewed_at = new Date().toISOString();
                persistUpdate("expressions_of_interest", "id", target.id, {
                    status: newStatus,
                    review_comment: target.review_comment,
                    reviewed_at: target.reviewed_at
                });
            } else {
                persistInsert("expressions_of_interest", {
                    id: "eoi-" + Date.now(),
                    student_email: p_student_email,
                    project_code: p_project_code,
                    status: newStatus,
                    message: "",
                    submitted_at: new Date().toISOString(),
                    reviewed_at: new Date().toISOString(),
                    review_comment: p_comment || null
                });
            }

            if (p_action === "accepted") {
                const members = liveDB.project_members || [];
                const alreadyMember = members.some(m =>
                    m.student_email.toLowerCase() === String(p_student_email).toLowerCase() &&
                    m.project_code.toLowerCase() === String(p_project_code).toLowerCase()
                );
                if (!alreadyMember) {
                    persistInsert("project_members", {
                        project_code: p_project_code,
                        student_email: p_student_email,
                        member_role: "Member",
                        joined_at: new Date().toISOString(),
                        left_at: null
                    });
                }
            }
            return Promise.resolve({ data: null, error: null });
        }

        return Promise.resolve({ data: null, error: null });
    }

